			},
			"type": "splunk.rectangle"
		},
		"viz_box_ex_inv": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ex_issues": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ex_net": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ex_wow": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ov_24h": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ov_bw": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ov_kpi": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ov_ssid": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_box_ov_week": {
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"rx": 10,
				"strokeColor": "rgba(0,0,0,0.08)"
			},
			"type": "splunk.rectangle"
		},
		"viz_cs_by_band": {
			"dataSources": {
				"primary": "ds_cs_by_band"
			},
			"description": "Client distribution across 2.4 GHz, 5 GHz, and 6 GHz bands",
			"options": {
				"seriesColorsByField": {
					"2.4 GHz": "#E5A823",
					"5 GHz": "#049FD9",
					"6 GHz": "#6EBE4A"
				},
				"showDonutHole": true
			},
			"title": "Clients by Band Type",
			"type": "splunk.pie"
		},
		"viz_cs_by_device": {
			"dataSources": {
				"primary": "ds_cs_by_device_type"
			},
			"description": "Top client device types by unique MAC count",
			"options": {
				"showDonutHole": true
			},
			"title": "Clients by Device Type",
			"type": "splunk.pie"
		},
		"viz_cs_by_location": {
			"dataSources": {
				"primary": "ds_cs_by_location_table"
			},
			"description": "Sites with the most connected clients",
			"options": {
				"count": 15,
				"fontSize": "small"
			},
			"title": "Top Networks by Client Count",
			"type": "splunk.table"
		},
		"viz_cs_by_proto": {
			"dataSources": {
				"primary": "ds_cs_by_protocol"
			},
			"description": "Client distribution by 802.11 protocol (ax, ac, n, etc.)",
			"options": {
				"dataValuesDisplay": "all",
				"seriesColors": [
					"#049FD9"
				],
				"yAxisTitleText": "Clients"
			},
			"title": "Clients by Wireless Protocol",
			"type": "splunk.bar"
		},
		"viz_cs_by_ssid": {
			"dataSources": {
				"primary": "ds_cs_by_ssid_table"
			},
			"description": "Client count per SSID — which networks are busiest",
			"options": {
				"count": 15,
				"fontSize": "small"
			},
			"title": "Top Networks by Client Count",
			"type": "splunk.table"
		},
		"viz_cs_count_trend": {
			"dataSources": {
				"primary": "ds_cs_count_over_time"
			},
			"description": "Client count over time colored by health status",
			"options": {
				"nullValueDisplay": "zero",
				"seriesColorsByField": {
					"Fair Count": "#E5A823",
					"Good Count": "#6EBE4A",
					"Idle Count": "#6E6E6E",
					"Poor Count": "#D64550"
				},
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Client Count"
			},
			"title": "Client Count Over Time — Health Distribution",
			"type": "splunk.area"
		},
		"viz_cs_hdr_activity": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Client Activity & Onboarding"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_hdr_location": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Client Distribution"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_hdr_session": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Client Session Distribution"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_hdr_traffic": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Client Traffic Distribution"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_hdr_trend": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Client Health Over Time"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_hdr_wireless": {
			"options": {
				"fontColor": "#005073",
				"markdown": "# Wireless Client Details"
			},
			"type": "splunk.markdown"
		},
		"viz_cs_health_by_loc": {
			"dataSources": {
				"primary": "ds_cs_health_by_loc_table"
			},
			"description": "Per-site client health breakdown — identify problem locations",
			"options": {
				"count": 15,
				"fontSize": "small"
			},
			"title": "Client Health by Location",
			"type": "splunk.table"
		},
		"viz_cs_health_dist": {
			"dataSources": {
				"primary": "ds_cs_health_dist"
			},
			"description": "Client health distribution — Healthy, Fair, Poor, Idle",
			"options": {
				"seriesColorsByField": {
					"FAIR": "#E5A823",
					"GOOD": "#6EBE4A",
					"IDLE": "#6E6E6E",
					"NODATA": "#999",
					"POOR": "#D64550"
				},
				"showDonutHole": true
			},
			"title": "Health Distribution",
			"type": "splunk.pie"
		},
		"viz_cs_health_kpi": {
			"context": {
				"trendColorEditorConfig": [
					{
						"to": 0,
						"value": "#6E6E6E"
					},
					{
						"from": 0,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_kpi_cs_health"
			},
			"description": "Average client health score from Catalyst Center",
			"options": {
				"majorColor": "#049FD9",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('Client Health Score') | lastPoint()",
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "#049FD9",
				"sparklineDisplay": "below",
				"sparklineStrokeColor": "#049FD9",
				"trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
				"trendDisplay": "percent",
				"unit": "%",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Client Health Score",
			"type": "splunk.singlevalue"
		},
		"viz_cs_onboard": {
			"dataSources": {
				"primary": "ds_cs_onboarding_table"
			},
			"description": "Average client association + DHCP + AAA onboarding time",
			"options": {
				"count": 5,
				"fontSize": "small"
			},
			"title": "Client Onboarding Time (Avg ms)",
			"type": "splunk.table"
		},
		"viz_cs_os": {
			"dataSources": {
				"primary": "ds_cs_os_dist"
			},
			"description": "Client operating system distribution by unique MAC count",
			"options": {
				"showDonutHole": true
			},
			"title": "Clients by Operating System",
			"type": "splunk.pie"
		},
		"viz_cs_session_band": {
			"dataSources": {
				"primary": "ds_cs_session_by_band"
			},
			"description": "Aggregate wireless session duration per radio band.",
			"options": {
				"seriesColorsByField": {
					"2.4 GHz": "#E5A823",
					"5 GHz": "#049FD9",
					"6 GHz": "#6EBE4A"
				},
				"showDonutHole": true
			},
			"title": "Session Hours by Band",
			"type": "splunk.pie"
		},
		"viz_cs_session_proto": {
			"dataSources": {
				"primary": "ds_cs_session_by_protocol"
			},
			"description": "Aggregate wireless session duration per protocol version.",
			"options": {
				"dataValuesDisplay": "all",
				"seriesColors": [
					"#049FD9"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Hours"
			},
			"title": "Session Hours by Protocol",
			"type": "splunk.bar"
		},
		"viz_cs_session_ssid": {
			"dataSources": {
				"primary": "ds_cs_session_by_ssid"
			},
			"description": "Top wireless networks ranked by aggregate client session duration.",
			"options": {
				"dataValuesDisplay": "all",
				"seriesColors": [
					"#049FD9"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Hours"
			},
			"title": "Top SSIDs by Session Hours",
			"type": "splunk.bar"
		},
		"viz_cs_top_clients": {
			"context": {
				"Usage__MB_ColumnFormatEditorConfig": {
					"number": {
						"thousandSeparated": true,
						"unit": "MB",
						"unitPosition": "after"
					}
				}
			},
			"dataSources": {
				"primary": "ds_cs_top_clients_table"
			},
			"description": "Highest data-consuming clients with SSID and usage",
			"options": {
				"columnFormat": {
					"Usage (MB)": {
						"align": "auto",
						"data": "> table | seriesByName(\"Usage (MB)\") | formatByType(Usage__MB_ColumnFormatEditorConfig)",
						"headerAlign": "auto",
						"textOverflow": "break-word"
					}
				},
				"count": 20,
				"fontSize": "small"
			},
			"title": "Top Clients by Data Usage",
			"type": "splunk.table"
		},
		"viz_cs_total_kpi": {
			"context": {
				"trendColorEditorConfig": [
					{
						"to": 0,
						"value": "#6E6E6E"
					},
					{
						"from": 0,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_kpi_cs_total"
			},
			"description": "Total unique clients connected during the time range",
			"options": {
				"majorColor": "#049FD9",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('Total Connected Clients') | lastPoint()",
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "#049FD9",
				"sparklineDisplay": "below",
				"sparklineStrokeColor": "#049FD9",
				"trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
				"trendDisplay": "percent",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Total Connected Clients",
			"type": "splunk.singlevalue"
		},
		"viz_cs_traffic_band": {
			"dataSources": {
				"primary": "ds_cs_traffic_by_band"
			},
			"description": "Total data transfer volume per wireless radio band.",
			"options": {
				"seriesColorsByField": {
					"2.4 GHz": "#E5A823",
					"5 GHz": "#049FD9",
					"6 GHz": "#6EBE4A"
				},
				"showDonutHole": true
			},
			"title": "Traffic by Band (MB)",
			"type": "splunk.pie"
		},
		"viz_cs_traffic_proto": {
			"dataSources": {
				"primary": "ds_cs_traffic_by_protocol"
			},
			"description": "Total data transfer volume per wireless protocol version.",
			"options": {
				"legendDisplay": "top",
				"nullValueDisplay": "connect",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "GB"
			},
			"title": "Traffic by Protocol Over Time",
			"type": "splunk.area"
		},
		"viz_cs_traffic_ssid": {
			"dataSources": {
				"primary": "ds_cs_traffic_by_ssid"
			},
			"description": "Top wireless networks ranked by total data transfer volume.",
			"options": {
				"legendDisplay": "top",
				"nullValueDisplay": "connect",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "GB"
			},
			"title": "Traffic by SSID Over Time",
			"type": "splunk.area"
		},
		"viz_cs_wired_wireless": {
			"dataSources": {
				"primary": "ds_cs_wireless_vs_wired"
			},
			"description": "Wired vs wireless client ratio",
			"options": {
				"seriesColorsByField": {
					"WIRED": "#E5A823",
					"WIRELESS": "#049FD9"
				},
				"showDonutHole": true
			},
			"title": "Wireless vs Wired",
			"type": "splunk.pie"
		},
		"viz_ex_ap_pct": {
			"context": {
				"trendColorEditorConfig": [
					{
						"to": 0,
						"value": "#6E6E6E"
					},
					{
						"from": 0,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_kpi_ex_ap_pct"
			},
			"description": "Percentage of APs reachable by Catalyst Center",
			"options": {
				"majorColor": "#049FD9",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('AP Reachability') | lastPoint()",
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "#049FD9",
				"sparklineDisplay": "below",
				"sparklineStrokeColor": "#049FD9",
				"trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
				"trendDisplay": "percent",
				"unit": "%",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "AP Reachability",
			"type": "splunk.singlevalue"
		},
		"viz_ex_ap_total": {
			"context": {
				"trendColorEditorConfig": [
					{
						"to": 0,
						"value": "#6E6E6E"
					},
					{
						"from": 0,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_kpi_ex_ap_total"
			},
			"description": "Total managed access points across all sites",
			"options": {
				"majorColor": "#049FD9",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('Access Points') | lastPoint()",
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "#049FD9",
				"sparklineDisplay": "below",
				"sparklineStrokeColor": "#049FD9",
				"trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
				"trendDisplay": "percent",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true
			},
			"title": "Access Points",
			"type": "splunk.singlevalue"
		},
		"viz_ex_cl_site_high": {
			"dataSources": {
				"primary": "ds_exec_client_site_top"
			},
			"description": "Sites with the best client health scores",
			"options": {
				"count": 10,
				"fontSize": "small"
			},
			"title": "Sites with Highest Client Health",
			"type": "splunk.table"
		},
		"viz_ex_cl_site_low": {
			"dataSources": {
