	"dataSources": {
		"ds_bw": {
			"name": "Statewide - ds_bandwidth_internet",
			"options": {
				"query": "| noop",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_bw_public": {
			"name": "Statewide - ds_bandwidth_public_internet",
			"options": {
				"query": "| noop",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_band": {
			"name": "Client Count by Band",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.band as band, connection.protocol as protocol | eval band=case(isnotnull(band) AND band!=\"null\", band, match(protocol, \"ax6\"), \"6 GHz\", match(protocol, \"ax\"), \"5 GHz\", match(protocol, \"ac\"), \"5 GHz\", match(protocol, \"n\"), \"2.4 GHz\", 1=1, \"Unknown\") | stats dc(macAddress) as clients by band",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_device_type": {
			"name": "Client Summary - ds_client_by_device_type",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| eval deviceType=if(isnull(deviceType) OR deviceType==\"null\" OR deviceType==\"\" OR deviceType==\"Un-Classified Device\", \"Unknown\", deviceType) \n| stats dc(macAddress) as clients by deviceType \n| sort -clients",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_location": {
			"name": "Client Summary - ds_client_by_location",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| eval Site=mvindex(split(siteHierarchy,\"/\"),-1) \n| where isnotnull(Site) AND Site!=\"null\" AND Site!=\"\" \n| stats dc(macAddress) as clients by Site \n| sort -clients",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_location_table": {
			"name": "Client Count by Location",
			"options": {
				"extend": "ds_cs_by_location",
				"query": "| rename clients as Clients"
			},
			"type": "ds.chain"
		},
		"ds_cs_by_protocol": {
			"name": "Client Count by Wireless Protocol",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.protocol as protocol | stats dc(macAddress) as clients by protocol | sort -clients",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_ssid": {
			"name": "Client Summary - ds_client_by_ssid",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" \n| stats dc(macAddress) as clients by connection.ssid \n| rename connection.ssid as ssid ",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_by_ssid_table": {
			"name": "Client Count by SSID",
			"options": {
				"extend": "ds_cs_by_ssid",
				"query": "| rename ssid as SSID, clients as Clients"
			},
			"type": "ds.chain"
		},
		"ds_cs_client_kpi": {
			"name": "Client Summary - ds_client_health_kpi",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\"\n| stats latest(scoreValue) as score, latest(clientCount) as total\n| eval health=round(score)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_count_over_time": {
			"name": "Client Summary - ds_client_count_over_time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRED\" OR clientType=\"WIRELESS\") (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| bin _time\n| stats latest(clientCount) as cc by _time, clientType, scoreType\n| stats sum(cc) as cc by _time, scoreType\n| eval \"Good Count\"=if(scoreType==\"GOOD\",cc,null()), \"Fair Count\"=if(scoreType==\"FAIR\",cc,null()), \"Poor Count\"=if(scoreType==\"POOR\",cc,null()), \"Idle Count\"=if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",cc,null())\n| stats sum(\"Good Count\") as \"Good Count\", sum(\"Fair Count\") as \"Fair Count\", sum(\"Poor Count\") as \"Poor Count\", sum(\"Idle Count\") as \"Idle Count\" by _time",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_health_by_loc_table": {
			"name": "Client Health by Location",
			"options": {
				"extend": "ds_cs_health_by_location",
				"query": "| rename health as \"Health %\", clients as Clients"
			},
			"type": "ds.chain"
		},
		"ds_cs_health_by_location": {
			"name": "Client Summary - ds_client_health_by_location",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| eval Site=mvindex(split(siteHierarchy,\"/\"),-1) \n| where isnotnull(Site) AND Site!=\"null\" AND Site!=\"\" \n| stats avg(health.overallScore) as sv, dc(macAddress) as clients by Site \n| eval health=round(sv*10, 2) \n| sort -clients \n| fields Site clients health",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_health_dist": {
			"name": "Client Summary - ds_client_health_dist",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRED\" OR clientType=\"WIRELESS\") (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| stats latest(clientCount) as cc by clientType, scoreType\n| stats sum(cc) as clients by scoreType",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_health_trend": {
			"name": "Client Health Score Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as \"Client Health Score\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_onboarding": {
			"name": "Client Summary - ds_client_onboarding",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| stats avg(onboarding.avgAuthDuration) as avg_aaa, avg(onboarding.avgDhcpDuration) as avg_dhcp, avg(onboarding.avgAssocDuration) as avg_assoc \n| eval avg_onboard=round(avg_aaa+avg_dhcp+avg_assoc, 2), avg_aaa=round(avg_aaa, 2), avg_dhcp=round(avg_dhcp, 2), avg_assoc=round(avg_assoc, 2)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_onboarding_table": {
			"name": "Client Onboarding Time",
			"options": {
				"extend": "ds_cs_onboarding",
				"query": "| rename avg_onboard as \"Total (ms)\", avg_aaa as \"AAA (ms)\", avg_dhcp as \"DHCP (ms)\", avg_assoc as \"Assoc (ms)\""
			},
			"type": "ds.chain"
		},
		"ds_cs_os_dist": {
			"name": "Client Summary - ds_client_os_dist",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| eval osType=if(isnull(osType) OR osType==\"null\" OR osType==\"\" OR osType==\"Un-Classified Device\", \"Unknown\", osType) \n| stats dc(macAddress) as clients by osType \n| rename osType as hostOs \n| sort -clients",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_session_by_band": {
			"name": "Client Session Duration by Band",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.band as band, connection.sessionDuration as sessionDuration | eval session_hrs=coalesce(sessionDuration,0)/3600 | eval band=coalesce(band, \"Unknown\") | stats sum(session_hrs) as total_hours, dc(macAddress) as clients by band | eval total_hours=round(total_hours, 2) | sort -total_hours",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_session_by_protocol": {
			"name": "Client Session Duration by Protocol",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.protocol as Protocol, connection.sessionDuration as sessionDuration | eval session_hrs=coalesce(sessionDuration,0)/3600 | stats sum(session_hrs) as total_hours, dc(macAddress) as clients by Protocol | eval total_hours=round(total_hours, 2) | sort -total_hours",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_session_by_ssid": {
			"name": "Client Session Duration by SSID",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.sessionDuration as sessionDuration, connection.ssid as SSID | eval session_hrs=coalesce(sessionDuration,0)/3600 | stats sum(session_hrs) as total_hours, dc(macAddress) as clients by SSID | eval total_hours=round(total_hours, 2) | sort -total_hours | head 10",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_top_clients": {
			"name": "Client Summary - ds_top_clients_by_usage",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" \n| stats sum(traffic.usage) as usage, latest(deviceType) as device_type, latest(connection.ssid) as ssid, latest(connection.l3Vn) as vn, latest(type) as conn_type, latest(siteHierarchy) as location by macAddress \n| eval usage_gb=tonumber(round(usage/1073741824,2)), ssid=case(isnotnull(ssid) AND ssid!=\"null\" AND ssid!=\"\", ssid, conn_type==\"Wired\" AND isnotnull(vn) AND vn!=\"null\", \"Wired (\".vn.\")\", conn_type==\"Wired\", \"Wired\", 1==1, \"Unknown\"), device_type=if(isnull(device_type) OR device_type==\"null\" OR device_type==\"\", \"Unknown\", device_type) \n| where usage_gb > 0 \n| sort -usage_gb \n| head 20 \n| fields macAddress device_type ssid location usage_gb",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_top_clients_table": {
			"name": "Top Clients by Data Usage",
			"options": {
				"extend": "ds_cs_top_clients",
				"query": "| rename macAddress as \"MAC\", device_type as \"Type\", ssid as SSID, location as Location, usage_gb as \"Usage (GB)\" | eval \"Usage (GB)\"=tonumber('Usage (GB)')"
			},
			"type": "ds.chain"
		},
		"ds_cs_total_trend": {
			"name": "Total Connected Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Total Connected Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_traffic_by_band": {
			"name": "Client Traffic by Band",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.band as band, traffic.* as * | eval total_bytes=coalesce(txBytes,0)+coalesce(rxBytes,0) | eval band=coalesce(band, \"Unknown\") | stats sum(total_bytes) as traffic_bytes, dc(macAddress) as clients by band | eval traffic_mb=round(traffic_bytes/1048576, 1) | sort -traffic_bytes",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_traffic_by_protocol": {
			"name": "Client Traffic by Protocol (timechart)",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.protocol as Protocol, traffic.* as * | eval total_bytes=coalesce(txBytes,0)+coalesce(rxBytes,0) | timechart sum(total_bytes) as traffic_bytes by Protocol fixedrange=false | foreach * [eval <<FIELD>>=if(\"<<FIELD>>\"!=\"_time\", round(<<FIELD>>/1073741824, 2), <<FIELD>>)]",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_traffic_by_ssid": {
			"name": "Client Traffic by SSID (timechart)",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" | rename connection.ssid as SSID, traffic.* as * | eval total_bytes=coalesce(txBytes,0)+coalesce(rxBytes,0) | timechart sum(total_bytes) as traffic_bytes by SSID fixedrange=false | foreach * [eval <<FIELD>>=if(\"<<FIELD>>\"!=\"_time\", round(<<FIELD>>/1073741824, 2), <<FIELD>>)]",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_wireless_vs_wired": {
			"name": "Client Summary - ds_wireless_vs_wired",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRELESS\" OR clientType=\"WIRED\") scoreType=\"ALL\"\n| stats latest(clientCount) as clients by clientType",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ex_ap_pct_trend": {
			"name": "AP Reachability Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | where match(DeviceFamily,\"(?i)ap|access.point|unified.ap\") | eval healthy=if(Reachability==\"Reachable\",1,0) | timechart fixedrange=false avg(healthy) as pct | eval \"AP Reachability\"=round(pct*100, 2)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
