		"ds_exec_ap_count": {
			"name": "Executive Summary - ds_ap_count",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| stats latest(DeviceFamily) as DeviceFamily, latest(Reachability) as Reachability by DeviceID\n| where match(DeviceFamily,\"(?i)ap|access.point|unified.ap\")\n| eval healthy=if(Reachability==\"Reachable\",1,0)\n| stats count as total, sum(healthy) as up\n| eval pct=round(up/total*100), down=total-up",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_client_health_by_site": {
			"name": "Executive Summary - ds_client_health_by_site",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval siteHierarchy=`dnac_site_normalize(siteHierarchy)`\n| where siteHierarchy!=\"\"\n| stats avg(health.overallScore) as health by type, siteHierarchy\n| eval health=round(health*10, 2)\n| chart avg(health) by siteHierarchy, type\n| rename Wireless as wireless, Wired as wired, siteHierarchy as Site\n| fields Site wireless wired",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_client_health_trend": {
			"name": "Executive Summary - ds_client_health_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as health | eval health=round(health, 2)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_client_site_bottom": {
