		"ds_exec_issue_priority_kpi": {
			"name": "Executive Summary - ds_issue_by_priority_kpi",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| stats dc(IssueID) as count by IssuePriority\n| eval p1=if(IssuePriority=\"P1\",count,0), p2=if(IssuePriority=\"P2\",count,0), p3=if(IssuePriority=\"P3\",count,0), p4=if(IssuePriority=\"P4\",count,0)\n| stats sum(p1) as p1, sum(p2) as p2, sum(p3) as p3, sum(p4) as p4",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_issue_summary": {
			"name": "Issue Summary (Total/Open/Resolved)",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" | stats dc(IssueID) as Total, dc(eval(if(IssueStatus==\"active\", IssueID, null()))) as Open, dc(eval(if(IssueStatus==\"resolved\", IssueID, null()))) as Resolved",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_issue_trend": {
			"name": "Executive Summary - ds_issue_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" | timechart count by IssueSpecificPriority",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_net_health_by_site": {
			"name": "Executive Summary - ds_network_health_by_site",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| where Site!=\"\"\n| stats latest(Reachability) as Reachability, latest(Manageability) as Manageability, latest(DeviceFamily) as DeviceFamily by DeviceID, Site\n| eval healthy=if(Reachability==\"Reachable\" AND match(Manageability,\"^Managed\"), 1, 0), cat=case(match(DeviceFamily,\"(?i)switch\"),\"Switch\", match(DeviceFamily,\"(?i)router\"),\"Router\", match(DeviceFamily,\"(?i)ap|access.point|unified.ap\"),\"Wireless\", 1==1,\"Third Party\")\n| stats avg(healthy) as health_pct, dc(eval(if(cat==\"Switch\",DeviceID,null()))) as switches, dc(eval(if(cat==\"Router\",DeviceID,null()))) as routers, dc(eval(if(cat==\"Wireless\",DeviceID,null()))) as wireless, dc(eval(if(cat==\"Third Party\",DeviceID,null()))) as third_party by Site\n| eval health_pct=round(health_pct*100)\n| sort health_pct",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_exec_net_site_bottom": {
			"name": "Sites with Lowest Health",
			"options": {
				"extend": "ds_exec_net_health_by_site",
				"query": "| sort health_pct | head 10 | rename health_pct as \"Health %\", switches as Switches, routers as Routers, wireless as \"Wireless/APs\", third_party as \"Third Party\""
			},
			"type": "ds.chain"
		},
		"ds_exec_net_site_top": {
			"name": "Sites with Highest Health",
			"options": {
				"extend": "ds_exec_net_health_by_site",
				"query": "| sort -health_pct | head 10 | rename health_pct as \"Health %\", switches as Switches, routers as Routers, wireless as \"Wireless/APs\", third_party as \"Third Party\""
			},
			"type": "ds.chain"
		},
		"ds_exec_network_health_trend": {
			"name": "Executive Summary - ds_network_health_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | timechart avg(eval(round(if(Reachability==\"Reachable\" AND match(Manageability,\"^Managed\"), 100, 0), 2))) as pct | eval pct=round(pct, 2)",
				"queryParameters": {
