			},
			"type": "ds.chain"
		},
		"ds_exec_wow_summary": {
			"name": "Week-over-Week KPI Comparison",
			"options": {
				"query": "| makeresults | eval x=1 | fields - x, _time | append [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\" earliest=-7d@d | stats dc(IssueID) as current_val | eval metric=\"Open Issues\" | appendcols [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\" earliest=-14d@d latest=-7d@d | stats dc(IssueID) as prev_val ]] | append [ search `index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" scoreValue>=0 earliest=-7d@d | stats latest(scoreValue) as current_val | eval metric=\"Client Health %\" | appendcols [ search `index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" scoreValue>=0 earliest=-14d@d latest=-7d@d | stats latest(scoreValue) as prev_val ]] | append [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" earliest=-7d@d | stats latest(Reachability) as r, latest(Manageability) as m by DeviceID | where r=\"Reachable\" AND match(m,\"^Managed\") | stats dc(DeviceID) as current_val | eval metric=\"Healthy Devices\" | appendcols [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" earliest=-14d@d latest=-7d@d | stats latest(Reachability) as r, latest(Manageability) as m by DeviceID | where r=\"Reachable\" AND match(m,\"^Managed\") | stats dc(DeviceID) as prev_val ]] | append [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" (DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Access Points\") earliest=-7d@d | stats latest(Reachability) as r by DeviceID | where r=\"Reachable\" | stats dc(DeviceID) as current_val | eval metric=\"Reachable APs\" | appendcols [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" (DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Access Points\") earliest=-14d@d latest=-7d@d | stats latest(Reachability) as r by DeviceID | where r=\"Reachable\" | stats dc(DeviceID) as prev_val ]] | where isnotnull(metric) | eval Change=if(isnum(prev_val) AND prev_val>0, round((current_val-prev_val)/prev_val*100,1), \"N/A\") | eval Change=case(Change=\"N/A\",\"N/A\", Change>0,\"+\".Change.\"%\", Change<0,Change.\"%\", Change=0,\"No change\", 1=1,\"N/A\") | rename metric as Metric, current_val as \"This Week\", prev_val as \"Last Week\" | table Metric, \"This Week\", \"Last Week\", Change",
				"queryParameters": {
					"earliest": "-14d@d",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
