		"ds_wired_kpi": {
			"name": "Statewide - ds_wired_health_kpi",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\"\n| stats latest(scoreValue) as sv, latest(clientCount) as total by scoreType\n| eval health=round(sv)\n| stats sum(eval(if(scoreType==\"ALL\", total, 0))) as total, avg(eval(if(scoreType==\"ALL\", health, null()))) as health, sum(eval(if(scoreType==\"GOOD\", total, 0))) as healthy, sum(eval(if(scoreType==\"FAIR\", total, 0))) as active, sum(eval(if(scoreType==\"POOR\", total, 0))) as inactive, sum(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\", total, 0))) as new_clients\n| eval health=round(health)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_total_trend": {
			"name": "Wired Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Wired Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_trend_24h": {
			"name": "Statewide - ds_wired_client_trend_24h",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType==\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType==\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType==\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",clientCount,null()))) as \"No Data\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_trend_7d": {
			"name": "Statewide - ds_wired_client_trend_24h",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType==\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType==\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType==\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",clientCount,null()))) as \"No Data\"",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_health_trend": {
			"name": "Wireless Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as \"Wireless Health\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_kpi": {
			"name": "Statewide - ds_wireless_health_kpi",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\"\n| stats latest(scoreValue) as sv, latest(clientCount) as total by scoreType\n| eval health=round(sv)\n| stats sum(eval(if(scoreType==\"ALL\", total, 0))) as total, avg(eval(if(scoreType==\"ALL\", health, null()))) as health, sum(eval(if(scoreType==\"GOOD\", total, 0))) as healthy, sum(eval(if(scoreType==\"FAIR\", total, 0))) as active, sum(eval(if(scoreType==\"POOR\", total, 0))) as inactive, sum(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\", total, 0))) as new_clients\n| eval health=round(health)",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_total_trend": {
			"name": "Wireless Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Wireless Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_trend_24h": {
			"name": "Statewide - ds_wireless_client_trend_24h",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType==\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType==\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType==\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",clientCount,null()))) as \"No Data\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_trend_7d": {
			"name": "Statewide - ds_wireless_client_trend_7d",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\") clientCount=*\n| timechart max(clientCount) as clientCount by scoreType",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			},
			"type": "ds.search"
		}
	},
